import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry tallskinny_matmul(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K
)
{
    .reg .u64 %rd<20>;
    .reg .u32 %r<20>;
    .reg .f32 %f<20>;
    .reg .pred %p<5>;

    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [M];
    ld.param.u32 %r2, [K];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r3, %ctaid.y;
    mov.u32 %r4, %ntid.y;
    mov.u32 %r5, %tid.y;
    mad.lo.s32 %r6, %r3, %r4, %r5;   // row

    mov.u32 %r7, %ctaid.x;
    mov.u32 %r8, %ntid.x;
    mov.u32 %r9, %tid.x;
    mad.lo.s32 %r10, %r7, %r8, %r9;  // col

    setp.ge.s32 %p1, %r6, %r1;
    setp.ge.s32 %p2, %r10, %r1;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;

    mov.f32 %f1, 0f00000000;

    mov.u32 %r11, 0;      // k

LOOP_START:
    setp.ge.s32 %p4, %r11, %r2;
    @%p4 bra LOOP_END;

    mad.lo.s32 %r12, %r6, %r2, %r11;   // a_idx = row*K + k
    mul.wide.s32 %rd4, %r12, 4;
    add.s64 %rd5, %rd1, %rd4;
    ld.global.f32 %f2, [%rd5];

    mad.lo.s32 %r13, %r11, %r1, %r10;  // b_idx = k*M + col
    mul.wide.s32 %rd6, %r13, 4;
    add.s64 %rd7, %rd2, %rd6;
    ld.global.f32 %f3, [%rd7];

    fma.rn.f32 %f1, %f2, %f3, %f1;

    add.s32 %r11, %r11, 1;
    bra LOOP_START;

LOOP_END:
    mad.lo.s32 %r14, %r6, %r1, %r10;   // c_idx = row*M + col
    mul.wide.s32 %rd8, %r14, 4;
    add.s64 %rd9, %rd3, %rd8;
    st.global.f32 [%rd9], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("tallskinny_matmul")

class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B) where one of the
    matrices is tall and skinny (M >> N or N >> M), implemented as a custom PTX kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 supported"
        assert A.is_contiguous() and B.is_contiguous(), "Inputs must be contiguous"

        M, K = A.shape
        K2, M2 = B.shape
        assert K == K2 and M == M2, "Shape mismatch for A @ B"

        C = torch.empty((M, M), dtype=A.dtype, device=A.device)

        module = _get_ptx_module()

        block_x, block_y = 16, 16
        grid_x = math.ceil(M / block_x)
        grid_y = math.ceil(M / block_y)

        module.launch(
            "tallskinny_matmul",
            grid=(grid_x, grid_y, 1),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, i32(M), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

